from typing import *
from collections import *

def separate_paren_groups(paren_string: str) -> List[str]:
    def is_valid(s: str) -> bool:
        stack = []
        for c in s:
            if c == '(':
                stack.append(c)
            elif c == ')':
                if not stack or stack[-1] != '(':
                    return False
                stack.pop()
        return not stack

    paren_string = paren_string.replace(' ', '')
    result = []
    start = 0
    for end in range(len(paren_string)):
        if paren_string[end] == '(':
            if is_valid(paren_string[start:end+1]):
                result.append(paren_string[start:end+1])
                start = end + 1
    return result

