def pluck(arr):
    if not arr:
        return []

    smallest_even = None
    smallest_index = None

    for index, value in enumerate(arr):
        if value % 2 == 0:
            if smallest_even is None or value < smallest_even:
                smallest_even = value
                smallest_index = index
            elif value == smallest_even:
                smallest_index = min(smallest_index, index)

    if smallest_even is not None:
        return [smallest_even, smallest_index]

    return []
