def search(lst):
    # Create a dictionary to store the frequency of each number
    freq = {}
    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the result as -1 (default if no such number exists)
    result = -1

    # Iterate over the frequency dictionary to find the greatest number meeting the criteria
    for num, count in freq.items():
        if count >= num:
            result = max(result, num)

    return result

