def search(lst):
    # Create a dictionary to store the frequency of each integer in the list
    freq = {}
    for num in lst:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Initialize the result as -1 (default if no value exists)
    result = -1

    # Iterate through the dictionary to find the required integer
    for num, count in freq.items():
        if num > 0 and count >= num:
            result = max(result, num)

    return result
