def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    vowels = 'aeiouAEIOU'
    encoded_message = []

    for char in message:
        if char.isalpha():
            # Swap case
            swapped_char = char.swapcase()
            # Replace vowel with the letter 2 places ahead
            if swapped_char in vowels:
                if swapped_char == 'A':
                    swapped_char = 'C'
                elif swapped_char == 'E':
                    swapped_char = 'G'
                elif swapped_char == 'I':
                    swapped_char = 'K'
                elif swapped_char == 'O':
                    swapped_char = 'Q'
                elif swapped_char == 'U':
                    swapped_char = 'W'
                elif swapped_char == 'a':
                    swapped_char = 'c'
                elif swapped_char == 'e':
                    swapped_char = 'g'
                elif swapped_char == 'i':
                    swapped_char = 'k'
                elif swapped_char == 'o':
                    swapped_char = 'q'
                elif swapped_char == 'u':
                    swapped_char = 'w'
            encoded_message.append(swapped_char)
        else:
            # Non-letter characters remain unchanged
            encoded_message.append(char)

    return ''.join(encoded_message)

# Example usage
print(encode('test'))  # Output: 'TGST'
print(encode('This is a message'))  # Output: 'tHKS KS C MGSSCGG'
