def encode(message):
    """
    Write a function that takes a message, and encodes in such a 
    way that it swaps case of all letters, replaces all vowels in 
    the message with the letter that appears 2 places ahead of that 
    vowel in the english alphabet. 
    Assume only letters. 

    Examples:
    >>> encode('test')
    'TGST'
    >>> encode('This is a message')
    'tHKS KS C MGSSCGG'
    """
    def swap_case(char):
        if char.islower():
            return char.upper()
        else:
            return char.lower()

    def replace_vowel(vowel):
        vowels = "aeiou"
        index = vowels.index(vowel)
        new_index = (index + 2) % len(vowels)
        return vowels[new_index]

    encoded_message = ""
    for char in message:
        if char.isalpha():
            if char in vowels:
                new_char = replace_vowel(char)
            else:
                new_char = swap_case(char)
            encoded_message += new_char
        else:
            encoded_message += char

    return encoded_message
