def move_one_ball(arr):
    # Check if the array is empty or has only one element
    if len(arr) <= 1:
        return True

    # Find the point where the array is split into two non-increasing parts
    break_point = -1
    for i in range(1, len(arr)):
        if arr[i] < arr[i - 1]:
            if break_point != -1:
                # Found more than one break point, cannot be sorted with one shift
                return False
            break_point = i

    # If no break point is found, the array is already sorted
    if break_point == -1:
        return True

    # Check if the array can be sorted by moving the break point to the end
    for i in range(break_point, len(arr) - 1):
        if arr[i + 1] < arr[i]:
            return False

    # Check if the first element is greater than the last element
    if arr[-1] > arr[0]:
        return False

    return True

