def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    first_string = lst[0]
    second_string = lst[1]

    # Check if concatenating in any order results in a balanced string
    if is_balanced(first_string + second_string) or is_balanced(second_string + first_string):
        return 'Yes'
    else:
        return 'No'

# Test cases
print(match_parens(['()(', ')']))  # Output: Yes
print(match_parens([')', ')']))     # Output: No
