from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]  # right, down, up, left

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    def dfs(x, y, path, visited, k):
        if k == 0:
            return path

        min_path = None
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                new_path = dfs(nx, ny, path + [grid[nx][ny]], visited, k - 1)
                visited.remove((nx, ny))

                if min_path is None or new_path < min_path:
                    min_path = new_path

        return min_path

    min_path = None
    for i in range(N):
        for j in range(N):
            visited = set([(i, j)])
            current_path = dfs(i, j, [grid[i][j]], visited, k - 1)
            if min_path is None or current_path < min_path:
                min_path = current_path

    return min_path

# Example usage:
print(minPath([[1, 2, 3], [4, 5, 6], [7, 8, 9]], 3))  # Output: [1, 2, 1]
print(minPath([[5, 9, 3], [4, 1, 6], [7, 8, 2]], 1))  # Output: [1]
