from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)

    # Function to perform BFS
    def bfs(start_row, start_col):
        visited = set()
        queue = [(start_row, start_col, [grid[start_row][start_col]])]

        while queue:
            row, col, path = queue.pop(0)

            # If path length reaches k, return the path
            if len(path) == k:
                return path

            # Explore neighbors
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                new_row, new_col = row + dr, col + dc

                # Check bounds and if not visited
                if 0 <= new_row < N and 0 <= new_col < N and (new_row, new_col) not in visited:
                    visited.add((new_row, new_col))
                    queue.append((new_row, new_col, path + [grid[new_row][new_col]]))

        return None

    # Try starting from each cell in the grid
    min_path = None
    for row in range(N):
        for col in range(N):
            path = bfs(row, col)
            if path is not None:
                if min_path is None or path < min_path:
                    min_path = path

    return min_path
